#!/usr/bin/env node
// Generate the Network Desk-derived parts of the NetOps SRE Agent plugin.
//
//   node scripts/netops/build-netops.mjs           # (re)write generated files
//   node scripts/netops/build-netops.mjs --check   # fail on drift (CI)
//
// Generated (never hand-edit):
//   plugins/netops/skills/<skill>/reference/INDEX.md
//   plugins/netops/skills/<skill>/reference/<specialist-dir>-role.md
//   plugins/netops/skills/<skill>/reference/<specialist-dir>-<sub-skill>.md
//   plugins/netops/agents/routing.json
//
// Reference docs are deliberately NOT named SKILL.md so SRE Agent's `skills/`
// discovery never registers them as extra skills. Hand-authored SKILL.md,
// engines and examples are never touched.

import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { REGISTRY } from "../../extensions/network-desk/registry.mjs";
import { NETOPS_PLUGIN, NETOPS_SKILLS, NETOPS_UTILITY_SKILLS } from "./netops-map.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(HERE, "..", "..");
const SPECIALISTS = join(REPO_ROOT, "extensions", "network-desk", "specialists");
const PLUGIN_DIR = join(REPO_ROOT, "plugins", "netops");
const MARKETPLACE = join(REPO_ROOT, ".github", "plugin", "marketplace.json");
const GENERATED_HEADER = "<!-- GENERATED by scripts/netops/build-netops.mjs from extensions/network-desk/specialists — do not edit. -->";

const posix = (p) => p.split("\\").join("/");
const lf = (s) => s.replace(/\r\n/g, "\n");

function fail(msg) {
    console.error(`✗ ${msg}`);
    process.exit(1);
}

function validateMap() {
    const errors = [];
    for (const [skill, def] of Object.entries(NETOPS_SKILLS)) {
        if (!/^netops-[a-z0-9-]+$/.test(skill)) errors.push(`${skill}: invalid skill name`);
        if (!def.title) errors.push(`${skill}: missing title`);
        if (!Array.isArray(def.symptoms) || def.symptoms.length === 0) errors.push(`${skill}: no symptoms`);
        for (const pattern of def.symptoms ?? []) {
            try { new RegExp(pattern, "i"); } catch (e) { errors.push(`${skill}: bad symptom /${pattern}/: ${e.message}`); }
            if (/\(\?<|\(\?<=|\(\?<!|\\p\{/.test(pattern)) errors.push(`${skill}: non-portable regex /${pattern}/`);
        }
        for (const [prefix, subs] of Object.entries(def.sources ?? {})) {
            const spec = REGISTRY[prefix];
            if (!spec) { errors.push(`${skill}: unknown specialist prefix '${prefix}'`); continue; }
            for (const sub of subs) {
                if (!spec.skills[sub]) errors.push(`${skill}: '${prefix}' has no sub-skill '${sub}'`);
                const src = join(SPECIALISTS, spec.dir, "skills", sub, "SKILL.md");
                if (!existsSync(src)) errors.push(`${skill}: missing source ${posix(relative(REPO_ROOT, src))}`);
            }
            const role = join(SPECIALISTS, spec.dir, "agents", `${spec.dir}.md`);
            if (!existsSync(role)) errors.push(`${skill}: missing role ${posix(relative(REPO_ROOT, role))}`);
        }
    }
    for (const util of NETOPS_UTILITY_SKILLS) {
        if (NETOPS_SKILLS[util]) errors.push(`${util}: utility skill must not carry specialist sources`);
    }
    if (errors.length) fail(`NetOps map validation failed:\n  - ${errors.join("\n  - ")}`);
}

// Returns Map<relativePathUnderPluginDir, content(LF)>.
export function expectedFiles() {
    validateMap();
    const files = new Map();
    for (const [skill, def] of Object.entries(NETOPS_SKILLS)) {
        const refDir = `skills/${skill}/reference`;
        const rows = [];
        for (const [prefix, subs] of Object.entries(def.sources)) {
            const spec = REGISTRY[prefix];
            const roleSrc = `extensions/network-desk/specialists/${spec.dir}/agents/${spec.dir}.md`;
            const roleOut = `${spec.dir}-role.md`;
            files.set(`${refDir}/${roleOut}`, lf(readFileSync(join(REPO_ROOT, roleSrc), "utf8")));
            rows.push(`| [${roleOut}](${roleOut}) | ${spec.name} — role | \`${roleSrc}\` |`);
            for (const sub of subs) {
                const src = `extensions/network-desk/specialists/${spec.dir}/skills/${sub}/SKILL.md`;
                const out = `${spec.dir}-${sub}.md`;
                files.set(`${refDir}/${out}`, lf(readFileSync(join(REPO_ROOT, src), "utf8")));
                rows.push(`| [${out}](${out}) | ${spec.name} — ${spec.skills[sub].replace(/\|/g, "\\|")} | \`${src}\` |`);
            }
        }
        files.set(`${refDir}/INDEX.md`, [
            GENERATED_HEADER,
            "",
            `# ${skill} — Network Desk reference material`,
            "",
            "Design-time background from the Network Desk specialists that this NetOps skill is built on.",
            "It is the same content the Network Desk Copilot CLI extension serves (single source of truth).",
            "",
            "- NetOps is **Azure-only**: apply only the Azure guidance here; ignore AWS/GCP/vendor sections.",
            "- The runtime procedure (managed scope, exact read-only commands, engine, output) is in `../SKILL.md` and always wins.",
            "- Network Desk content is advisory. Verify every Azure fact against Microsoft Learn before acting on it.",
            "",
            "| File | Content | Source |",
            "| --- | --- | --- |",
            ...rows,
            "",
        ].join("\n"));
    }

    const routing = {
        _generated: "scripts/netops/build-netops.mjs from scripts/netops/netops-map.mjs — do not edit",
        plugin: NETOPS_PLUGIN.name,
        version: NETOPS_PLUGIN.version,
        flags: "i",
        fallbackSkill: "netops-routing-analyzer",
        skills: Object.entries(NETOPS_SKILLS).map(([skill, def], order) => ({
            skill,
            title: def.title,
            order,
            specialists: Object.keys(def.sources).map((p) => `cn_${p}`),
            symptoms: def.symptoms,
        })),
        utilitySkills: NETOPS_UTILITY_SKILLS,
    };
    files.set("agents/routing.json", JSON.stringify(routing, null, 2) + "\n");

    const pluginManifest = {
        name: NETOPS_PLUGIN.name,
        version: NETOPS_PLUGIN.version,
        description: NETOPS_PLUGIN.description,
        license: "MIT",
        skills: ["skills/"],
    };
    files.set("plugin.json", JSON.stringify(pluginManifest, null, 2) + "\n");
    return files;
}

export function marketplaceEntry() {
    return {
        name: NETOPS_PLUGIN.name,
        description: NETOPS_PLUGIN.marketplaceDescription,
        version: NETOPS_PLUGIN.version,
        source: "./plugins/netops",
    };
}

// Upsert the netops entry into the repo marketplace, preserving every other entry.
export function mergedMarketplace(existingText) {
    const market = JSON.parse(existingText);
    const plugins = Array.isArray(market.plugins) ? market.plugins : [];
    const others = plugins.filter((p) => p.name !== NETOPS_PLUGIN.name);
    market.plugins = [...others, marketplaceEntry()];
    return JSON.stringify(market, null, 2) + "\n";
}

function generatedReferenceDirs() {
    return Object.keys(NETOPS_SKILLS).map((s) => join(PLUGIN_DIR, "skills", s, "reference"));
}

function listFiles(dir) {
    if (!existsSync(dir)) return [];
    return readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
        e.isDirectory() ? listFiles(join(dir, e.name)) : [join(dir, e.name)]);
}

export function check() {
    const expected = expectedFiles();
    const drift = [];
    for (const [rel, content] of expected) {
        const abs = join(PLUGIN_DIR, rel);
        if (!existsSync(abs)) drift.push(`missing ${rel}`);
        else if (lf(readFileSync(abs, "utf8")) !== content) drift.push(`stale ${rel}`);
    }
    for (const dir of generatedReferenceDirs()) {
        for (const abs of listFiles(dir)) {
            const rel = posix(relative(PLUGIN_DIR, abs));
            if (!expected.has(rel)) drift.push(`unexpected ${rel}`);
        }
    }
    for (const abs of listFiles(join(PLUGIN_DIR, "skills"))) {
        const rel = posix(relative(PLUGIN_DIR, abs));
        if (/\/reference\/.*SKILL\.md$/i.test(rel)) drift.push(`nested SKILL.md not allowed: ${rel}`);
    }
    const market = lf(readFileSync(MARKETPLACE, "utf8"));
    if (mergedMarketplace(market) !== market) drift.push("stale .github/plugin/marketplace.json (netops entry)");
    return drift;
}

export function write() {
    const expected = expectedFiles();
    for (const dir of generatedReferenceDirs()) rmSync(dir, { recursive: true, force: true });
    for (const [rel, content] of expected) {
        const abs = join(PLUGIN_DIR, rel);
        mkdirSync(dirname(abs), { recursive: true });
        writeFileSync(abs, content);
    }
    writeFileSync(MARKETPLACE, mergedMarketplace(readFileSync(MARKETPLACE, "utf8")));
    return expected.size;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    if (process.argv.includes("--check")) {
        const drift = check();
        if (drift.length) fail(`NetOps generated files drifted — run \`npm run build:netops\`:\n  - ${drift.join("\n  - ")}`);
        console.log(`✓ NetOps generated files up to date (${Object.keys(NETOPS_SKILLS).length} skills)`);
    } else {
        const n = write();
        console.log(`✓ Wrote ${n} NetOps generated files under ${posix(relative(REPO_ROOT, PLUGIN_DIR))}/`);
    }
}
